int Parent(int root,const char* relative) {
  Fd current(fcntl(root,F_DUPFD_CLOEXEC,0));
  if(current.fd<0)return -1;
  std::string name(relative);size_t start=0,end=0;
  while((end=name.find('/',start))!=std::string::npos){
    const std::string part=name.substr(start,end-start);
    if(part.empty()||part=="."||part==".."){errno=EINVAL;return -1;}
    Fd next(openat(current.fd,part.c_str(),kRead|O_DIRECTORY));
    if(next.fd<0)return -1;
    struct stat st{};if(fstat(next.fd,&st)!=0||!S_ISDIR(st.st_mode)||!Private(st)){errno=EACCES;return -1;}
    std::swap(current.fd,next.fd);
    start=end+1;
  }
  return current.release();
}
